from __future__ import annotations

from enum import StrEnum
from typing import Any, Literal, Protocol

from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator

from foreman.hooks import (
    HookAction,
    HookError,
    HookEvent,
    HookEventKind,
    HookOutcome,
)


class HookAdapter(Protocol):
    """Translate one coding assistant's hook protocol at Foreman's boundary."""

    client: str

    def parse(self, payload: dict[str, Any]) -> HookEvent: ...

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]: ...


class CodexHookEventName(StrEnum):
    SESSION_START = "SessionStart"
    USER_PROMPT_SUBMIT = "UserPromptSubmit"
    PRE_TOOL_USE = "PreToolUse"
    POST_TOOL_USE = "PostToolUse"
    STOP = "Stop"
    SESSION_END = "SessionEnd"


class CodexHookInput(BaseModel):
    """The stable subset of Codex lifecycle input consumed by its adapter."""

    model_config = ConfigDict(extra="allow")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    hook_event_name: CodexHookEventName
    turn_id: str | None = None
    prompt: str | None = None
    tool_name: str | None = None
    tool_use_id: str | None = None
    tool_input: Any = None
    tool_response: Any = None
    stop_hook_active: bool = False
    last_assistant_message: str | None = None

    @model_validator(mode="after")
    def required_event_fields(self) -> CodexHookInput:
        if self.hook_event_name is CodexHookEventName.USER_PROMPT_SUBMIT and not (
            self.prompt and self.prompt.strip()
        ):
            raise ValueError("UserPromptSubmit requires a non-empty prompt")
        if self.hook_event_name in {
            CodexHookEventName.PRE_TOOL_USE,
            CodexHookEventName.POST_TOOL_USE,
        } and not self.tool_name:
            raise ValueError(f"{self.hook_event_name.value} requires tool_name")
        return self


_CODEX_EVENT_KINDS = {
    CodexHookEventName.SESSION_START: HookEventKind.SESSION_STARTED,
    CodexHookEventName.USER_PROMPT_SUBMIT: HookEventKind.WORK_SUBMITTED,
    CodexHookEventName.PRE_TOOL_USE: HookEventKind.BEFORE_TOOL,
    CodexHookEventName.POST_TOOL_USE: HookEventKind.AFTER_TOOL,
    CodexHookEventName.STOP: HookEventKind.WORKER_STOPPING,
    CodexHookEventName.SESSION_END: HookEventKind.SESSION_ENDED,
}


class CodexHookAdapter:
    client = "codex"

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = CodexHookInput.model_validate(payload)
        except ValidationError as error:
            raise HookError(f"invalid Codex hook input: {error}") from error
        return HookEvent(
            client=self.client,
            session_id=source.session_id,
            cwd=source.cwd,
            kind=_CODEX_EVENT_KINDS[source.hook_event_name],
            source_event_name=source.hook_event_name.value,
            turn_id=source.turn_id,
            prompt=source.prompt,
            tool_name=source.tool_name,
            tool_use_id=source.tool_use_id,
            tool_input=source.tool_input,
            tool_response=source.tool_response,
            continuation_active=source.stop_hook_active,
            last_assistant_message=source.last_assistant_message,
        )

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]:
        reason = outcome.reason or "Foreman blocked this operation"
        if outcome.action is HookAction.ALLOW:
            return {}
        if outcome.action is HookAction.INJECT_CONTEXT:
            return {
                "hookSpecificOutput": {
                    "hookEventName": event.source_event_name,
                    "additionalContext": reason,
                }
            }
        if outcome.action is HookAction.BLOCK:
            if event.kind is HookEventKind.BEFORE_TOOL:
                return {
                    "hookSpecificOutput": {
                        "hookEventName": event.source_event_name,
                        "permissionDecision": "deny",
                        "permissionDecisionReason": reason,
                    }
                }
            return {"decision": "block", "reason": reason}
        return {
            "continue": False,
            "stopReason": reason,
            "systemMessage": outcome.system_message or reason,
        }


class DeepAgentsHookInput(BaseModel):
    """Published dcode Hooks v2 wire subset, including failed tool calls."""

    model_config = ConfigDict(extra="allow")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    hook_event_name: Literal[
        "SessionStart", "UserPromptSubmit", "PreToolUse", "PostToolUse",
        "PostToolUseFailure", "Stop", "SessionEnd",
    ]
    prompt_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    prompt: str | None = None
    tool_name: str | None = None
    tool_use_id: str | None = None
    tool_input: Any = None
    tool_response: Any = None
    stop_hook_active: bool = False
    last_assistant_message: str | None = None
    error: str | None = None
    is_interrupt: bool | None = None

    @model_validator(mode="after")
    def required_deepagents_fields(self) -> DeepAgentsHookInput:
        if self.hook_event_name == "UserPromptSubmit" and not (
            self.prompt and self.prompt.strip()
        ):
            raise ValueError("UserPromptSubmit requires a non-empty prompt")
        if self.hook_event_name in {"PreToolUse", "PostToolUse", "PostToolUseFailure"}:
            if not self.tool_name or not self.tool_use_id:
                raise ValueError("tool events require tool_name and tool_use_id")
        if self.hook_event_name == "PostToolUseFailure" and self.error is None:
            raise ValueError("PostToolUseFailure requires error")
        return self


class DeepAgentsHookAdapter(CodexHookAdapter):
    # dcode accepts the same decision/context output vocabulary as Codex.
    # Post-tool stop directives are feedback in dcode; Stop and prompt hooks
    # provide the actionable turn boundary (see the integration guide).
    client = "deepagents"

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = DeepAgentsHookInput.model_validate(payload)
            kind = (
                HookEventKind.AFTER_TOOL
                if source.hook_event_name == "PostToolUseFailure"
                else _CODEX_EVENT_KINDS[source.hook_event_name]
            )
            response = source.tool_response
            if source.hook_event_name == "PostToolUseFailure":
                response = {"isError": True, "error": source.error}
                if source.is_interrupt is not None:
                    response["is_interrupt"] = source.is_interrupt
            return HookEvent(
                client=self.client,
                session_id=source.session_id,
                cwd=source.cwd,
                kind=kind,
                source_event_name=source.hook_event_name,
                work_id=source.prompt_id,
                turn_id=source.prompt_id,
                prompt=source.prompt,
                tool_name=source.tool_name,
                tool_use_id=source.tool_use_id,
                tool_input=source.tool_input,
                tool_response=response,
                continuation_active=source.stop_hook_active,
                last_assistant_message=source.last_assistant_message,
            )
        except (ValidationError, ValueError) as error:
            raise HookError(f"invalid Deep Agents hook input: {error}") from error


class PiHookInput(BaseModel):
    """Bridge envelope around Pi's native events; identities come from its host."""

    model_config = ConfigDict(extra="forbid")

    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    event: dict[str, Any]
    work_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    event_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    continuation_active: bool = False


_PI_EVENT_KINDS = {
    "session_start": HookEventKind.SESSION_STARTED,
    "input": HookEventKind.WORK_SUBMITTED,
    "tool_call": HookEventKind.BEFORE_TOOL,
    "tool_result": HookEventKind.AFTER_TOOL,
    "agent_before_settle": HookEventKind.WORKER_STOPPING,
    "session_shutdown": HookEventKind.SESSION_ENDED,
}
_DURABLE_EVENT_KINDS = {
    "beforeRequest": HookEventKind.WORK_SUBMITTED,
    "beforeTool": HookEventKind.BEFORE_TOOL,
    "afterTool": HookEventKind.AFTER_TOOL,
    "onYield": HookEventKind.WORKER_STOPPING,
}


class PiHookAdapter:
    client = "pi"
    event_kinds = _PI_EVENT_KINDS

    def parse(self, payload: dict[str, Any]) -> HookEvent:
        try:
            source = PiHookInput.model_validate(payload)
            native = source.event
            name = native.get("type")
            if name not in self.event_kinds:
                raise ValueError(f"unsupported event {name!r}")
            durable = self.client == "pi-durable"
            call = native.get("call", {}) if durable else native
            if not isinstance(call, dict):
                raise ValueError("call must be an object")
            return HookEvent(
                client=self.client,
                session_id=source.session_id,
                cwd=source.cwd,
                kind=self.event_kinds[name],
                source_event_name=name,
                work_id=source.work_id,
                event_id=source.event_id,
                turn_id=source.work_id,
                prompt=native.get("prompt" if durable else "text"),
                tool_name=call.get("name" if durable else "toolName"),
                tool_use_id=call.get("id" if durable else "toolCallId"),
                tool_input=call.get("arguments" if durable else "input"),
                tool_response=native.get("result") if durable else (
                    {key: native[key]
                     for key in ("content", "details", "structuredContent", "isError")
                     if key in native} if name == "tool_result" else None
                ),
                continuation_active=source.continuation_active,
                last_assistant_message=native.get("last_assistant_message"),
            )
        except (ValidationError, ValueError, TypeError) as error:
            raise HookError(f"invalid {self.client} hook input: {error}") from error

    def render(self, event: HookEvent, outcome: HookOutcome) -> dict[str, Any]:
        # The TypeScript bridges apply these effects through native APIs. A HALT
        # remains distinct from BLOCK (which requests a completion continuation).
        if outcome.action is HookAction.ALLOW:
            return {}
        return outcome.model_dump(mode="json", exclude_none=True)


class PiDurableHookAdapter(PiHookAdapter):
    client = "pi-durable"
    event_kinds = _DURABLE_EVENT_KINDS


_ADAPTERS: dict[str, HookAdapter] = {
    CodexHookAdapter.client: CodexHookAdapter(),
    DeepAgentsHookAdapter.client: DeepAgentsHookAdapter(),
    PiHookAdapter.client: PiHookAdapter(),
    PiDurableHookAdapter.client: PiDurableHookAdapter(),
}


def hook_adapter(client: str) -> HookAdapter:
    normalized = client.strip().lower()
    try:
        return _ADAPTERS[normalized]
    except KeyError:
        available = ", ".join(sorted(_ADAPTERS))
        raise HookError(
            f"unsupported hook client {client!r}; available clients: {available}"
        ) from None


def available_hook_clients() -> tuple[str, ...]:
    return tuple(sorted(_ADAPTERS))

from __future__ import annotations

import hashlib
import json
import os
import subprocess
import tempfile
import time
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import UTC, datetime, timedelta
from enum import StrEnum
from pathlib import Path
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator

from foreman.config import FactoryConfig
from foreman.evidence import run_command_evidence_providers, selected_command_evidence
from foreman.foreman import ForemanModel, ForemanModelError
from foreman.models import (
    FactoryState,
    FactoryStatus,
    Intervention,
    InterventionType,
    WorkerRecord,
    WorkerStatus,
    WorkerType,
)
from foreman.observation import build_observation
from foreman.paths import foreman_data_dir
from foreman.policy import FactoryPolicy
from foreman.responsibilities import ResponsibilityRegistry
from foreman.routing import (
    ResponsibilityRouter,
    ResponsibilityRoutingError,
    RouteGroup,
    resolve_hierarchical_routing,
)


class HookError(RuntimeError):
    """A hook event or attached-worker session could not be processed safely."""


class HookEventKind(StrEnum):
    """Assistant-neutral lifecycle events understood by Foreman."""

    SESSION_STARTED = "session_started"
    WORK_SUBMITTED = "work_submitted"
    BEFORE_TOOL = "before_tool"
    AFTER_TOOL = "after_tool"
    WORKER_STOPPING = "worker_stopping"
    SESSION_ENDED = "session_ended"


class HookEvent(BaseModel):
    """Normalized event produced by a coding-assistant adapter."""

    model_config = ConfigDict(extra="forbid")

    client: str = Field(min_length=1, max_length=100)
    session_id: str = Field(min_length=1, max_length=1_000)
    cwd: str = Field(min_length=1)
    kind: HookEventKind
    source_event_name: str = Field(min_length=1)
    turn_id: str | None = None
    work_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    event_id: str | None = Field(default=None, min_length=1, max_length=1_000)
    prompt: str | None = None
    tool_name: str | None = None
    tool_use_id: str | None = None
    tool_input: Any = None
    tool_response: Any = None
    continuation_active: bool = False
    last_assistant_message: str | None = None

    @model_validator(mode="after")
    def required_event_fields(self) -> HookEvent:
        if self.kind is HookEventKind.WORK_SUBMITTED and not (
            self.prompt and self.prompt.strip()
        ):
            raise ValueError("work_submitted requires a non-empty prompt")
        if (
            self.kind in {HookEventKind.BEFORE_TOOL, HookEventKind.AFTER_TOOL}
            and not self.tool_name
        ):
            raise ValueError(f"{self.kind.value} requires tool_name")
        return self


class HookAction(StrEnum):
    """Assistant-neutral effect requested by Foreman."""

    ALLOW = "allow"
    INJECT_CONTEXT = "inject_context"
    BLOCK = "block"
    HALT = "halt"


class HookOutcome(BaseModel):
    """A semantic hook result that an assistant adapter can render."""

    model_config = ConfigDict(extra="forbid")

    action: HookAction = HookAction.ALLOW
    reason: str | None = None
    system_message: str | None = None


class AttachedSession(BaseModel):
    """Bounded local state shared by hook calls from one interactive worker."""

    model_config = ConfigDict(extra="forbid")

    schema_version: int = 2
    client: str = "codex"
    session_id: str
    prompt_routed: bool = False
    work_id: str | None = None
    work_prompt: str | None = None
    routed_context: str | None = None
    continuation_requested: bool = False
    replayed_outcomes: list[dict[str, Any]] = Field(default_factory=list)
    repository: str
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    expires_at: datetime
    event_count: int = Field(default=0, ge=0)
    recent_events: list[dict[str, Any]] = Field(default_factory=list)
    state: FactoryState | None = None

    def touch(self, ttl_seconds: float) -> None:
        now = datetime.now(UTC)
        self.updated_at = now
        self.expires_at = now + timedelta(seconds=ttl_seconds)


def default_foreman_data_dir() -> Path:
    return foreman_data_dir()


class AttachedSessionStore:
    """Atomic, process-safe storage for human-initiated worker sessions."""

    def __init__(
        self,
        data_dir: Path | str | None = None,
        *,
        ttl_seconds: float = 604_800.0,
        lock_timeout_seconds: float = 30.0,
    ) -> None:
        self.data_dir = (
            Path(data_dir).expanduser().resolve()
            if data_dir is not None
            else default_foreman_data_dir()
        )
        self.sessions_dir = self.data_dir / "sessions"
        self.locks_dir = self.sessions_dir / ".locks"
        self.ttl_seconds = ttl_seconds
        self.lock_timeout_seconds = lock_timeout_seconds

    @staticmethod
    def _key(session_id: str, client: str = "codex") -> str:
        identity = f"{client}\0{session_id}"
        return hashlib.sha256(identity.encode("utf-8")).hexdigest()

    def path_for(self, session_id: str, client: str = "codex") -> Path:
        return self.sessions_dir / f"{self._key(session_id, client)}.json"

    def _prepare(self) -> None:
        self.locks_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        try:
            os.chmod(self.sessions_dir, 0o700)
            os.chmod(self.locks_dir, 0o700)
        except OSError:
            pass

    @contextmanager
    def locked(self, session_id: str, client: str = "codex") -> Iterator[None]:
        self._prepare()
        lock_path = self.locks_dir / f"{self._key(session_id, client)}.lock"
        deadline = time.monotonic() + self.lock_timeout_seconds
        stale_after = max(60.0, self.lock_timeout_seconds * 4)
        descriptor: int | None = None
        while descriptor is None:
            try:
                descriptor = os.open(
                    lock_path,
                    os.O_CREAT | os.O_EXCL | os.O_WRONLY,
                    0o600,
                )
                os.write(descriptor, f"{os.getpid()}\n".encode())
            except FileExistsError:
                try:
                    age = time.time() - lock_path.stat().st_mtime
                    if age > stale_after:
                        lock_path.unlink()
                        continue
                except FileNotFoundError:
                    continue
                if time.monotonic() >= deadline:
                    raise HookError(f"timed out locking hook session {session_id!r}") from None
                time.sleep(0.05)
        try:
            yield
        finally:
            os.close(descriptor)
            try:
                lock_path.unlink()
            except FileNotFoundError:
                pass

    def new(
        self,
        session_id: str,
        repository: Path,
        client: str = "codex",
    ) -> AttachedSession:
        now = datetime.now(UTC)
        return AttachedSession(
            client=client,
            session_id=session_id,
            repository=str(repository),
            created_at=now,
            updated_at=now,
            expires_at=now + timedelta(seconds=self.ttl_seconds),
        )

    def load(self, session_id: str, client: str = "codex") -> AttachedSession | None:
        path = self.path_for(session_id, client)
        try:
            session = AttachedSession.model_validate_json(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return None
        except (OSError, ValidationError, ValueError) as error:
            raise HookError(f"hook session {session_id!r} is malformed: {error}") from error
        if session.session_id != session_id or session.client != client:
            raise HookError(f"hook session identity mismatch for {session_id!r}")
        if session.expires_at <= datetime.now(UTC):
            self.delete(session_id, client)
            return None
        return session

    def save(self, session: AttachedSession) -> None:
        self._prepare()
        target = self.path_for(session.session_id, session.client)
        payload = session.model_dump_json(indent=2)
        descriptor, temporary = tempfile.mkstemp(
            prefix="session-", suffix=".tmp", dir=self.sessions_dir
        )
        try:
            try:
                if hasattr(os, "fchmod"):
                    os.fchmod(descriptor, 0o600)
                else:
                    os.chmod(temporary, 0o600)
            except OSError:
                pass
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                handle.write(payload)
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
        except Exception:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def delete(self, session_id: str, client: str = "codex") -> None:
        try:
            self.path_for(session_id, client).unlink()
        except FileNotFoundError:
            pass

    def purge_expired(self) -> int:
        if not self.sessions_dir.exists():
            return 0
        now = datetime.now(UTC)
        removed = 0
        for path in self.sessions_dir.glob("*.json"):
            try:
                session = AttachedSession.model_validate_json(path.read_text(encoding="utf-8"))
            except (OSError, ValidationError, ValueError):
                continue
            if session.expires_at <= now:
                try:
                    path.unlink()
                    removed += 1
                except FileNotFoundError:
                    pass
        return removed


def _repository_root(cwd: str) -> Path:
    directory = Path(cwd).expanduser().resolve()
    if not directory.is_dir():
        raise HookError(f"hook cwd is not a directory: {directory}")
    try:
        result = subprocess.run(
            ["git", "-C", str(directory), "rev-parse", "--show-toplevel"],
            check=False,
            capture_output=True,
            text=True,
            timeout=5,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return directory
    if result.returncode != 0 or not result.stdout.strip():
        return directory
    return Path(result.stdout.strip()).resolve()


def _bounded_json(value: Any, limit: int) -> str:
    try:
        rendered = json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
    except (TypeError, ValueError):
        rendered = repr(value)
    if len(rendered) <= limit:
        return rendered
    return f"[... {len(rendered) - limit} earlier characters omitted ...]{rendered[-limit:]}"


def _event_record(event: HookEvent, limit: int) -> dict[str, Any]:
    details: dict[str, Any] = {}
    if event.prompt is not None:
        details["prompt"] = event.prompt
    if event.tool_name is not None:
        details["tool_name"] = event.tool_name
    if event.tool_input is not None:
        details["tool_input"] = event.tool_input
    if event.tool_response is not None:
        details["tool_response"] = event.tool_response
    if event.last_assistant_message is not None:
        details["last_assistant_message"] = event.last_assistant_message
    return {
        "client": event.client,
        "event": event.kind.value,
        "source_event": event.source_event_name,
        "turn_id": event.turn_id,
        "recorded_at": datetime.now(UTC).isoformat(),
        "summary": _bounded_json(details, limit),
    }


class AttachedWorkerRuntime:
    """Route and supervise normalized lifecycle events from an attached worker."""

    def __init__(
        self,
        *,
        model: ForemanModel,
        router: ResponsibilityRouter,
        responsibilities: ResponsibilityRegistry,
        config: FactoryConfig,
        store: AttachedSessionStore | None = None,
        routing_groups: tuple[RouteGroup, ...] = (),
        active_extension_ids: tuple[str, ...] = (),
        extension_snapshot_revisions: dict[str, str] | None = None,
    ) -> None:
        self.model = model
        self.router = router
        self.candidates = responsibilities
        self.config = config
        self.store = store or AttachedSessionStore(ttl_seconds=config.hook_session_ttl_seconds)
        self.routing_groups = routing_groups
        self.active_extension_ids = active_extension_ids
        self.extension_snapshot_revisions = dict(extension_snapshot_revisions or {})

    async def handle(self, event: HookEvent) -> HookOutcome:
        repository = _repository_root(event.cwd)
        self.store.purge_expired()
        with self.store.locked(event.session_id, event.client):
            if event.kind is HookEventKind.SESSION_ENDED:
                self.store.delete(event.session_id, event.client)
                return HookOutcome()

            session = self.store.load(event.session_id, event.client) or self.store.new(
                event.session_id, repository, event.client
            )
            if event.event_id is not None:
                fingerprint = hashlib.sha256(event.model_dump_json().encode()).hexdigest()
                for cached in session.replayed_outcomes:
                    if cached["event_id"] == event.event_id:
                        if cached["fingerprint"] != fingerprint:
                            raise HookError("event_id was reused with different input")
                        return HookOutcome.model_validate(cached["outcome"])
            session.repository = str(repository)
            session.event_count += 1
            session.recent_events.append(_event_record(event, self.config.output_limit))
            session.recent_events = session.recent_events[-self.config.event_history_limit :]

            if event.kind is HookEventKind.SESSION_STARTED:
                session.touch(self.store.ttl_seconds)
                self.store.save(session)
                return HookOutcome()
            if event.kind is HookEventKind.WORK_SUBMITTED:
                try:
                    if event.work_id is not None and event.work_id == session.work_id:
                        if session.work_prompt != event.prompt.strip():
                            raise HookError("work_id was reused with a different prompt")
                        if session.state is not None and (
                            session.state.active_extension_ids != list(self.active_extension_ids)
                            or session.state.extension_snapshot_revisions
                            != self.extension_snapshot_revisions
                        ):
                            raise HookError("extension snapshots changed; submit new work")
                        output = HookOutcome(
                            action=HookAction.INJECT_CONTEXT,
                            reason=session.routed_context,
                        ) if session.routed_context else HookOutcome()
                    else:
                        output = await self._route_prompt(session, event)
                        session.work_id = event.work_id
                        session.work_prompt = event.prompt.strip()
                        session.routed_context = output.reason
                        session.continuation_requested = False
                except ResponsibilityRoutingError as error:
                    output = HookOutcome(
                        action=HookAction.BLOCK,
                        reason=f"Foreman could not route this work: {error}",
                    )
            else:
                if session.state is None:
                    if session.prompt_routed and not self.candidates.global_ids():
                        return HookOutcome()
                    raise HookError(
                        f"{event.source_event_name} arrived before work_submitted"
                    )
                if (
                    session.state.active_extension_ids != list(self.active_extension_ids)
                    or
                    session.state.extension_snapshot_revisions
                    != self.extension_snapshot_revisions
                ):
                    raise HookError(
                        "extension snapshots changed during this attached session; "
                        "submit the work prompt again"
                    )
                if event.kind is HookEventKind.WORKER_STOPPING and session.work_id is not None:
                    event = event.model_copy(update={
                        "continuation_active": (
                            event.continuation_active or session.continuation_requested
                        ),
                    })
                output = await self._assess_event(session, event)
                if (
                    event.kind is HookEventKind.WORKER_STOPPING
                    and session.work_id is not None
                    and output.action is HookAction.BLOCK
                ):
                    session.continuation_requested = True

            if event.event_id is not None:
                session.replayed_outcomes.append({
                    "event_id": event.event_id,
                    "fingerprint": fingerprint,
                    "outcome": output.model_dump(mode="json"),
                })
                session.replayed_outcomes = session.replayed_outcomes[
                    -self.config.event_history_limit :
                ]
            self._bound_state(session)
            session.touch(self.store.ttl_seconds)
            self.store.save(session)
            return output

    async def _route_prompt(
        self, session: AttachedSession, event: HookEvent
    ) -> HookOutcome:
        assert event.prompt is not None
        decision = await resolve_hierarchical_routing(
            event.prompt.strip(),
            self.candidates,
            self.routing_groups,
            self.router,
            require_match=bool(self.candidates.global_ids()),
        )
        active_ids = decision.active_responsibility_ids
        session.prompt_routed = True
        if not active_ids:
            if not self.candidates.global_ids():
                session.state = None
                return HookOutcome()
            raise ResponsibilityRoutingError("routing activated no responsibilities")
        guidance = "\n\n".join(
            text for responsibility_id in active_ids
            if (text := self.candidates.context_for(responsibility_id))
        )
        if len(guidance) > self.config.field_limit:
            raise HookError("selected responsibility context exceeds the field limit")

        state = session.state or FactoryState(
            run_id=(
                f"attached-{AttachedSessionStore._key(session.session_id, session.client)[:16]}"
            ),
            job=event.prompt.strip(),
            repository=session.repository,
            max_iterations=self.config.max_iterations,
            candidate_responsibility_ids=[
                responsibility.id for responsibility in self.candidates.responsibilities
            ],
        )
        state.job = event.prompt.strip()
        state.repository = session.repository
        state.status = FactoryStatus.RUNNING
        state.finished_at = None
        state.iteration = 0
        state.max_iterations = self.config.max_iterations
        state.active_responsibility_ids = active_ids
        state.routing_scores = dict(decision.scores)
        state.routing_bindings = decision.bindings
        state.routing_trace = [item.model_dump(mode="json") for item in decision.trace]
        state.active_extension_ids = list(self.active_extension_ids)
        state.extension_snapshot_revisions = dict(self.extension_snapshot_revisions)
        state.retry_count = 0
        state.consecutive_assessment_failures = 0
        state.verification_started = False
        state.verification_completed = False

        worker_id = "attached-worker"
        worker = WorkerRecord(
            worker_id=worker_id,
            worker_type=WorkerType.CODING,
            mission=event.prompt.strip(),
            status=WorkerStatus.RUNNING,
            started_at=datetime.now(UTC),
            client=session.client,
            client_session_id=session.session_id,
            client_turn_id=event.turn_id,
            supports_steering=True,
        )
        state.workers = [worker]
        state.active_workers = [worker_id]
        state.completed_workers = []
        state.failed_workers = []
        state.latest_result = None
        state.latest_intervention = None
        state.touch()
        session.state = state

        names = ", ".join(active_ids)
        return HookOutcome(
            action=HookAction.INJECT_CONTEXT,
            reason=f"Foreman attached. Active responsibilities: {names}."
            + (f"\n\n{guidance}" if guidance else ""),
        )

    async def _assess_event(
        self, session: AttachedSession, event: HookEvent
    ) -> HookOutcome:
        state = session.state
        assert state is not None
        active = self.candidates.routed(state.active_responsibility_ids)
        worker = state.workers[0]
        worker.client_turn_id = event.turn_id or worker.client_turn_id
        summary = session.recent_events[-1]["summary"]
        worker.stdout = f"{worker.stdout}\n{event.kind.value}: {summary}".strip()
        if len(worker.stdout) > self.config.output_limit:
            worker.stdout = worker.stdout[-self.config.output_limit :]

        if event.kind is HookEventKind.WORKER_STOPPING:
            worker.status = WorkerStatus.COMPLETED
            worker.finished_at = datetime.now(UTC)
            state.active_workers = []
            state.completed_workers = [worker.worker_id]
            providers = selected_command_evidence(
                active.checks(), self.config.command_evidence
            )
            results = await run_command_evidence_providers(
                providers,
                Path(state.repository),
                worker_id=worker.worker_id,
                output_limit=self.config.output_limit,
            )
            state.command_evidence.extend(results)
        else:
            worker.status = WorkerStatus.RUNNING
            worker.finished_at = None
            state.active_workers = [worker.worker_id]
            state.completed_workers = []

        state.iteration += 1
        state.touch()
        observation = await build_observation(
            state,
            self.config,
            recent_events=session.recent_events,
            current_operation=event.model_dump(
                mode="json",
                include={
                    "client", "kind", "source_event_name", "turn_id", "tool_name",
                    "tool_use_id", "tool_input",
                },
                exclude_none=True,
            ),
            repository_instruction_files=active.repository_instruction_files(),
        )
        try:
            result = await self.model.assess(observation, active.checks())
        except ForemanModelError as error:
            state.errors.append(str(error))
            state.consecutive_assessment_failures += 1
            return self._assessment_failure_output(event, str(error))

        state.consecutive_assessment_failures = 0
        evaluated = FactoryPolicy(
            self.config,
            active,
            enforce_iteration_limit=False,
        ).evaluate(state, result)
        directive = evaluated.selected_directive
        assert directive is not None
        state.latest_result = evaluated
        state.result_history.append(evaluated)
        state.latest_intervention = directive
        state.intervention_history.append(directive)
        output = self._directive_output(event, directive, state, worker)
        state.touch()
        return output

    def _assessment_failure_output(self, event: HookEvent, reason: str) -> HookOutcome:
        message = f"Foreman could not evaluate this operation: {reason}"
        if event.kind in {HookEventKind.BEFORE_TOOL, HookEventKind.AFTER_TOOL}:
            return HookOutcome(action=HookAction.BLOCK, reason=message)
        if event.kind is HookEventKind.WORKER_STOPPING and not event.continuation_active:
            return HookOutcome(action=HookAction.BLOCK, reason=message)
        return HookOutcome(action=HookAction.HALT, reason=message, system_message=message)

    def _directive_output(
        self,
        event: HookEvent,
        directive: Intervention,
        state: FactoryState,
        worker: WorkerRecord,
    ) -> HookOutcome:
        action = directive.action
        reason = directive.reason
        if action is InterventionType.STEER_WORKER:
            worker.steer_count += 1
            worker.last_steered_at = datetime.now(UTC)

        if event.kind is HookEventKind.BEFORE_TOOL:
            if action in {InterventionType.ESCALATE, InterventionType.STOP_WORKER}:
                return HookOutcome(action=HookAction.BLOCK, reason=reason)
            if action is InterventionType.STEER_WORKER:
                return HookOutcome(action=HookAction.INJECT_CONTEXT, reason=reason)
            return HookOutcome()

        if event.kind is HookEventKind.AFTER_TOOL:
            if action is InterventionType.ESCALATE:
                state.status = FactoryStatus.ESCALATED
                state.finished_at = datetime.now(UTC)
                return HookOutcome(
                    action=HookAction.HALT,
                    reason=reason,
                    system_message=reason,
                )
            if action is InterventionType.STOP_WORKER:
                worker.status = WorkerStatus.STOPPED
                worker.finished_at = datetime.now(UTC)
                state.active_workers = []
                return HookOutcome(action=HookAction.BLOCK, reason=reason)
            if action is InterventionType.STEER_WORKER:
                return HookOutcome(action=HookAction.INJECT_CONTEXT, reason=reason)
            return HookOutcome()

        if event.kind is not HookEventKind.WORKER_STOPPING:
            return HookOutcome()
        if action is InterventionType.FINISH:
            state.status = FactoryStatus.FINISHED
            state.finished_at = datetime.now(UTC)
            return HookOutcome()
        if action is InterventionType.ESCALATE:
            state.status = FactoryStatus.ESCALATED
            state.finished_at = datetime.now(UTC)
            return HookOutcome(
                action=HookAction.HALT,
                reason=reason,
                system_message=reason,
            )
        if event.continuation_active:
            return HookOutcome(
                action=HookAction.HALT,
                reason=reason,
                system_message=(
                    "Foreman still found unfinished work after one automatic continuation: "
                    f"{reason}"
                ),
            )
        if action is InterventionType.START_VERIFIER:
            state.verification_started = True
        worker.status = WorkerStatus.RUNNING
        worker.finished_at = None
        state.active_workers = [worker.worker_id]
        state.completed_workers = []
        return HookOutcome(action=HookAction.BLOCK, reason=reason)

    def _bound_state(self, session: AttachedSession) -> None:
        state = session.state
        if state is None:
            return
        limit = self.config.worker_history_limit
        state.result_history = state.result_history[-limit:]
        state.intervention_history = state.intervention_history[-limit:]
        evidence_limit = max(limit, len(self.config.command_evidence) * limit)
        state.command_evidence = state.command_evidence[-evidence_limit:]
        state.errors = state.errors[-limit:]

    async def close(self) -> None:
        try:
            await self.model.close()
        finally:
            await self.router.close()


